def shipWithinDays(weights, days):
    left, right = max(weights), sum(weights)
    while left < right:
        mid = (left + right) // 2
        needed = 1
        cur = 0
        for w in weights:
            if cur + w > mid:
                needed += 1
                cur = 0
            cur += w
        if needed <= days:
            right = mid
        else:
            left = mid + 1
    return left
